/**
 * @file src/stats/statsTabData.ts
 * Structured view-models for Svelte stats tabs.
 */

import type { GameRuntime } from '../types/game.js';
import { ACHIEVEMENTS } from '../../constants/questsAchievements.ts';
import { formatNumber } from '../../formatters.ts';
import { ZONES as _ZONES } from '../../constants/balance/zonesAndPacing.ts';
import { currentZone } from '../../gameManager.ts';

const ZONES = _ZONES as Record<number, { name: string }>;

export const SVELTE_STATS_TABS = [
  'combat',
  'creatures',
  'economy',
  'records',
  'tower',
  'quests',
  'growth',
] as const;

export type SvelteStatsTab = (typeof SVELTE_STATS_TABS)[number];

export interface StatsMetricRow {
  label: string;
  value: string;
  highlight?: boolean;
  extra?: string;
  sub?: string;
  wide?: boolean;
  valueStyle?: string;
}

export interface StatsRankedRow {
  rank: number;
  label: string;
  value: string;
  sub?: string;
  spriteUrl?: string;
}

export interface StatsCombatTopZoneRow {
  rank: number;
  zoneName: string;
  combats: string;
  sub: string;
}

export interface StatsCombatTabData {
  sessionBanner: StatsMetricRow | null;
  metrics: StatsMetricRow[];
  advancedMetrics: StatsMetricRow[];
  topZones: StatsCombatTopZoneRow[];
  topZonesEmpty: boolean;
}

export interface StatsEconomyTabData {
  sessionBanner: StatsMetricRow | null;
  metrics: StatsMetricRow[];
  rocketMetrics: StatsMetricRow[];
}

export interface StatsCreaturesTabData {
  sessionBanner: StatsMetricRow | null;
  creaturesMetrics: StatsMetricRow[];
  extraMetrics: StatsMetricRow[];
  pokedexMetrics: StatsMetricRow[];
  ivMetrics: StatsMetricRow[];
  topContributors: StatsRankedRow[];
  topContributorsEmpty: boolean;
}

export interface StatsRecordsTabData {
  sessionBanner: StatsMetricRow | null;
  recordsMetrics: StatsMetricRow[];
  trainerScore: StatsMetricRow | null;
}

export interface StatsTowerTabData {
  sessionBanner: StatsMetricRow | null;
  metrics: StatsMetricRow[];
}

export interface StatsQuestsTabData {
  sessionBanner: StatsMetricRow | null;
  metrics: StatsMetricRow[];
  nearAchievements: StatsRankedRow[];
  nearAchievementsEmpty: boolean;
}

export interface StatsGrowthTabData {
  sessionBanner: StatsMetricRow | null;
  progressionMetrics: StatsMetricRow[];
  weeklyMetrics: StatsMetricRow[];
}

function statsT(game: GameRuntime, key: string, vars: Record<string, unknown> = {}): string {
  return game.t(`statsUi.${key}`, vars);
}

function sessionBannerRow(game: GameRuntime, tabKey: string): StatsMetricRow | null {
  const sessionDiff = game._getStatsSessionDiff?.() ?? null;
  if (!sessionDiff) return null;
  let line = '';
  if (tabKey === 'combat') {
    const c = sessionDiff.combatsWon || 0;
    const cap = sessionDiff.creaturesObtained || 0;
    const sh = sessionDiff.shiniesObtained || 0;
    if (c === 0 && cap === 0 && sh === 0) return null;
    line = statsT(game, 'sessionCombatsLine', { combats: c, captures: cap, shinies: sh });
  } else if (tabKey === 'creatures') {
    const cap = sessionDiff.creaturesObtained || 0;
    const sh = sessionDiff.shiniesObtained || 0;
    const eg = sessionDiff.eggsOpened || 0;
    if (cap === 0 && sh === 0 && eg === 0) return null;
    line = `+${cap} ${statsT(game, 'weeklyCapturesLabel')} • +${sh} ${statsT(game, 'weeklyShiniesLabel')} • +${eg} ${statsT(game, 'eggsOpened')}`;
  } else if (tabKey === 'economy') {
    const e = sessionDiff.totalPokedollarsEarned || 0;
    const sp = sessionDiff.totalPokedollarsSpent || 0;
    if (e === 0 && sp === 0) return null;
    line = statsT(game, 'sessionEconomyLine', { earned: formatNumber(e), spent: formatNumber(sp) });
  } else if (tabKey === 'records') {
    const sc = sessionDiff.trainerScore || 0;
    const fl = sessionDiff.towerFloorsClimbed || 0;
    if (sc === 0 && fl === 0) return null;
    line = statsT(game, 'sessionRecordsLine', { score: formatNumber(sc), floors: formatNumber(fl) });
  } else if (tabKey === 'tower') {
    const fl = sessionDiff.towerFloorsClimbed || 0;
    const tm = sessionDiff.triumphMarks || 0;
    if (fl === 0 && tm === 0) return null;
    line = `+${formatNumber(fl)} ${statsT(game, 'towerFloorsTotal')} • +${formatNumber(tm)} ${statsT(game, 'triumphMarksBalance')}`;
  } else if (tabKey === 'quests') {
    const qt = sessionDiff.questTokens || 0;
    if (qt === 0) return null;
    line = `+${formatNumber(qt)} ${statsT(game, 'questTokensBalance')}`;
  } else if (tabKey === 'growth') {
    const evos = sessionDiff.evolutionsCount || 0;
    const eggs = sessionDiff.eggsOpened || 0;
    if (evos === 0 && eggs === 0) return null;
    line = `+${formatNumber(evos)} ${statsT(game, 'evolutions')} • +${formatNumber(eggs)} ${statsT(game, 'eggsOpened')}`;
  }
  if (!line) return null;
  return {
    label: statsT(game, 'sessionDiff', { value: line }),
    value: '',
    wide: true,
  };
}

function formatDurationMs(ms: number): string {
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

export function buildCombatTabData(game: GameRuntime): StatsCombatTabData {
  const s = game.stats || {};
  const totalCombats = (s.combatsWon || 0) + (s.combatsLost || 0);
  const winRate = totalCombats > 0 ? ((s.combatsWon / totalCombats) * 100).toFixed(1) : '0';

  const topZonesRaw = game._getTopZones?.(3) ?? [];
  const topZones: StatsCombatTopZoneRow[] = topZonesRaw.map((z: any, idx: any) => {
    const zoneEntry = ZONES?.[z.id];
    const zoneName = zoneEntry
      ? game.getLocalizedZoneName(z.id, zoneEntry.name)
      : `Zone #${z.id}`;
    return {
      rank: idx + 1,
      zoneName,
      combats: formatNumber(z.combats),
      sub: statsT(game, 'topZoneRow', {
        combats: formatNumber(z.combats),
        bosses: formatNumber((z.bosses || 0) + (z.epics || 0)),
        trainers: formatNumber(z.trainers || 0),
      }),
    };
  });

  const ultimates = (s.ultimateUsed || 0) + (s.ultimateUsedManual || 0);

  return {
    sessionBanner: sessionBannerRow(game, 'combat'),
    metrics: [
      {
        label: statsT(game, 'combatsWon'),
        value: formatNumber(s.combatsWon || 0),
        highlight: true,
        extra: statsT(game, 'winRate', { value: winRate }),
      },
      { label: statsT(game, 'combatsLost'), value: formatNumber(s.combatsLost || 0) },
      { label: statsT(game, 'bossesDefeated'), value: formatNumber(s.bossDefeated || 0), highlight: true },
      { label: statsT(game, 'epicsDefeated'), value: formatNumber(s.epicDefeated || 0) },
      { label: statsT(game, 'damageDealt'), value: formatNumber(s.totalDamageDealt || 0) },
      { label: statsT(game, 'damageTaken'), value: formatNumber(s.totalDamageTaken || 0) },
    ],
    advancedMetrics: [
      { label: statsT(game, 'ultimatesUsed'), value: formatNumber(ultimates) },
      { label: statsT(game, 'statusInflicted'), value: formatNumber(s.statusInflicted || 0) },
      { label: statsT(game, 'moveStatusInflicted'), value: formatNumber(s.moveStatusInflicted || 0) },
      { label: statsT(game, 'longestCombatTurns'), value: formatNumber(s.longestCombatTurns || 0) },
    ],
    topZones,
    topZonesEmpty: topZones.length === 0,
  };
}

export function buildEconomyTabData(game: GameRuntime): StatsEconomyTabData {
  const s = game.stats || {};
  return {
    sessionBanner: sessionBannerRow(game, 'economy'),
    metrics: [
      { label: statsT(game, 'economyBalance'), value: formatNumber(game.pokedollars || 0), highlight: true },
      { label: statsT(game, 'economyEarned'), value: formatNumber(s.totalPokedollarsEarned || 0) },
      { label: statsT(game, 'economySpent'), value: formatNumber(s.totalPokedollarsSpent || 0) },
      { label: statsT(game, 'economyPeak'), value: formatNumber(s.peakPokedollars || 0) },
      { label: statsT(game, 'totalRocketInterests'), value: formatNumber(s.totalRocketBankInterestGained || 0) },
      { label: statsT(game, 'rocketSpins'), value: formatNumber(s.rocketCasinoSpins || 0) },
      { label: statsT(game, 'economyDustRecycled'), value: formatNumber(s.essenceDustRecycled || 0) },
    ],
    rocketMetrics: [
      { label: statsT(game, 'rocketTrustLevelMax'), value: formatNumber(s.rocketTrustLevelMax || 0) },
      { label: statsT(game, 'rocketCasinoWins'), value: formatNumber(s.rocketCasinoWinningSpins || 0) },
      { label: statsT(game, 'rocketCasinoFullBoards'), value: formatNumber(s.rocketCasinoFullBoards || 0) },
      { label: statsT(game, 'rocketLargeLoansRepaid'), value: formatNumber(s.rocketLargeLoansRepaid || 0) },
    ],
  };
}

export function buildCreaturesTabData(game: GameRuntime): StatsCreaturesTabData {
  const s = game.stats || {};
  const totalCreatures = game.playerTeam.length + game.storage.length + game.pension.length;
  const shinyRate = (s.eggsOpened || 0) > 0
    ? ((s.shiniesObtained / s.eggsOpened) * 100).toFixed(3)
    : '0';

  const dex = game._computePokedexCompletion?.() ?? { caught: 0, total: 0, shinyCaught: 0, shinyTotal: 0 };
  const dexPct = dex.total > 0 ? ((dex.caught / dex.total) * 100).toFixed(1) : '0.0';
  const shinyPct = dex.shinyTotal > 0 ? ((dex.shinyCaught / dex.shinyTotal) * 100).toFixed(2) : '0.00';

  const iv = game._computeAvgIv?.() ?? { teamAvg: 0, teamPct: 0, storageAvg: 0, storagePct: 0, perfectCount: 0 };
  const top = game._getTopDpsContributors?.(10) ?? [];

  return {
    sessionBanner: sessionBannerRow(game, 'creatures'),
    creaturesMetrics: [
      {
        label: statsT(game, 'creaturesOwned'),
        value: String(totalCreatures),
        highlight: true,
        wide: true,
        sub: statsT(game, 'teamPensionStorage', {
          team: game.playerTeam.length,
          pension: game.pension.length,
          storage: game.storage.length,
        }),
      },
      { label: statsT(game, 'creaturesObtained'), value: formatNumber(s.creaturesObtained || 0) },
      {
        label: statsT(game, 'shiniesObtained'),
        value: String(s.shiniesObtained || 0),
        highlight: true,
        extra: statsT(game, 'rateShort', { value: shinyRate }),
      },
      { label: statsT(game, 'eggsOpened'), value: formatNumber(s.eggsOpened || 0) },
      { label: statsT(game, 'evolutions'), value: formatNumber(s.evolutionsCount || 0) },
      { label: statsT(game, 'prestiges'), value: formatNumber(s.prestigeCount || 0), highlight: true },
    ],
    extraMetrics: [
      { label: statsT(game, 'manualCaptures'), value: formatNumber(s.manualCaptures || 0) },
      { label: statsT(game, 'ivUpgrades'), value: formatNumber(s.ivUpgrades || 0) },
      { label: statsT(game, 'pokerusInfections'), value: formatNumber(s.pokerusInfections || 0) },
      { label: statsT(game, 'shadowiesObtained'), value: formatNumber(s.shadowiesObtained || 0) },
    ],
    pokedexMetrics: [
      {
        label: statsT(game, 'pokedexCompletion'),
        value: statsT(game, 'pokedexCount', { caught: dex.caught, total: dex.total, pct: dexPct }),
        highlight: true,
      },
      {
        label: statsT(game, 'pokedexShiny'),
        value: statsT(game, 'pokedexCount', { caught: dex.shinyCaught, total: dex.shinyTotal, pct: shinyPct }),
      },
    ],
    ivMetrics: [
      {
        label: statsT(game, 'avgIvTeam'),
        value: statsT(game, 'avgIvValue', { avg: iv.teamAvg.toFixed(1), pct: iv.teamPct.toFixed(1) }),
        highlight: true,
      },
      {
        label: statsT(game, 'avgIvStorage'),
        value: statsT(game, 'avgIvValue', { avg: iv.storageAvg.toFixed(1), pct: iv.storagePct.toFixed(1) }),
      },
      { label: statsT(game, 'avgIvPerfect'), value: formatNumber(iv.perfectCount) },
    ],
    topContributors: top.map((entry: any, idx: any) => {
      const snap = entry.snap ?? {};
      const baseName = typeof snap.name === 'string' ? snap.name : `#${entry.id}`;
      const name = baseName + (snap.isShiny ? ' ★' : '');
      return {
        rank: idx + 1,
        label: name,
        value: formatNumber(entry.total),
        spriteUrl: typeof snap.sprite === 'string' ? snap.sprite : undefined,
      };
    }),
    topContributorsEmpty: top.length === 0,
  };
}

export function buildRecordsTabData(game: GameRuntime): StatsRecordsTabData {
  const s = game.stats || {};
  const longestSec = Math.round(s.longestCombatSeconds || 0);
  const score = game.computeTrainerScore();
  const rank = game.getTrainerRank(score);
  const rankName = statsT(game, rank.active.key);
  const nextLine = rank.next
    ? statsT(game, 'rankNext', { name: statsT(game, rank.next.key), score: formatNumber(rank.next.min) })
    : statsT(game, 'rankMax');
  const rankBadge = `<span style="display:inline-block;padding:2px 10px;border-radius:6px;background:${rank.active.color}22;color:${rank.active.color};font-weight:600">${rankName}</span>`;

  return {
    sessionBanner: sessionBannerRow(game, 'records'),
    recordsMetrics: [
      {
        label: statsT(game, 'longestCombat'),
        value: longestSec > 0 ? statsT(game, 'longestCombatSeconds', { value: longestSec }) : '—',
      },
      { label: statsT(game, 'longestWinStreak'), value: formatNumber(s.longestWinStreak || 0) },
      { label: statsT(game, 'longestDryStreakShiny'), value: formatNumber(s.longestDryStreakShinyEver || 0) },
      { label: statsT(game, 'highestPokemonLevel'), value: String(s.highestLevelReached || 0) },
    ],
    trainerScore: {
      label: statsT(game, 'trainerScore'),
      value: formatNumber(score),
      highlight: true,
      wide: true,
      extra: rankBadge,
      sub: `${nextLine}<br>${statsT(game, 'trainerScoreBreakdown')}`,
    },
  };
}

export function buildTowerTabData(game: GameRuntime): StatsTowerTabData {
  const s = game.stats || {};
  return {
    sessionBanner: sessionBannerRow(game, 'tower'),
    metrics: [
      { label: statsT(game, 'towerRecord'), value: formatNumber(game.towerRecord || 0), highlight: true },
      { label: statsT(game, 'towerFloorsTotal'), value: formatNumber(s.towerFloorsClimbed || 0) },
      { label: statsT(game, 'towerRunsPlayed'), value: formatNumber(s.towerRunsPlayed || 0) },
      { label: statsT(game, 'towerRunsForfeited'), value: formatNumber(s.towerRunsForfeited || 0) },
      {
        label: statsT(game, 'triumphMarksEarned'),
        value: formatNumber(s.totalTriumphMarksEarned || 0),
        sub: `${statsT(game, 'triumphMarksBalance')}: ${formatNumber(game.triumphMarks || 0)}`,
      },
    ],
  };
}

export function buildQuestsTabData(game: GameRuntime): StatsQuestsTabData {
  const s = game.stats || {};
  const totalAch = Object.keys(ACHIEVEMENTS || {}).length;
  const doneAch = game._countAchievementsCompleted?.() ?? 0;
  const near = game._getNearestAchievements?.(3) ?? [];

  return {
    sessionBanner: sessionBannerRow(game, 'quests'),
    metrics: [
      {
        label: statsT(game, 'achievementsCompleted'),
        value: statsT(game, 'achievementsTotal', { done: doneAch, total: totalAch }),
        highlight: true,
      },
      { label: statsT(game, 'storyQuestsCompleted'), value: formatNumber((game.completedStoryQuests || []).length) },
      { label: statsT(game, 'classicQuestsCompleted'), value: formatNumber(s.classicQuestsCompleted || 0) },
      {
        label: statsT(game, 'questTokensEarned'),
        value: formatNumber(s.totalQuestTokensEarned || 0),
        sub: `${statsT(game, 'questTokensBalance')}: ${formatNumber(game.questTokens || 0)}`,
      },
    ],
    nearAchievements: near.map((a: any, idx: any) => {
      const loc = game.getLocalizedAchievementData(a.id, a.def);
      const pct = (a.ratio * 100).toFixed(1);
      return {
        rank: idx + 1,
        label: loc.title || a.id,
        value: `${pct}%`,
        sub: `${formatNumber(a.current)}/${formatNumber(a.target)}`,
      };
    }),
    nearAchievementsEmpty: near.length === 0,
  };
}

export function buildGrowthTabData(game: GameRuntime): StatsGrowthTabData {
  const s = game.stats || {};
  const currentPlayTime = (s.totalPlayTime || 0) + (Date.now() - (s.startTime || Date.now()));
  const hours = Math.floor(currentPlayTime / 3600000);
  const minutes = Math.floor((currentPlayTime % 3600000) / 60000);
  const seconds = Math.floor((currentPlayTime % 60000) / 1000);
  const zoneId = Number(currentZone) || 0;
  const zoneName = ZONES?.[zoneId]
    ? game.getLocalizedZoneName(zoneId, ZONES[zoneId].name)
    : statsT(game, 'unknownZone');
  const maxLevel = game.playerTeam.length > 0
    ? Math.max(...game.playerTeam.map((c) => c.level))
    : 0;

  const wkDiff = game._getStatsWeeklyDiff?.();
  const weeklyMetrics: StatsMetricRow[] = [];
  if (!wkDiff) {
    weeklyMetrics.push({
      label: statsT(game, 'weeklyComparisonEmpty'),
      value: '',
      wide: true,
      sub: statsT(game, 'weeklyComparisonHint'),
    });
  } else {
    const items = [
      { key: 'combatsWon', label: statsT(game, 'weeklyCombatsLabel') },
      { key: 'creaturesObtained', label: statsT(game, 'weeklyCapturesLabel') },
      { key: 'shiniesObtained', label: statsT(game, 'weeklyShiniesLabel') },
      { key: 'totalDamageDealt', label: statsT(game, 'weeklyDamageLabel') },
      { key: 'totalPokedollarsEarned', label: statsT(game, 'weeklyMoneyLabel') },
      { key: 'trainerScore', label: statsT(game, 'weeklyScoreLabel') },
    ];
    for (const it of items) {
      const d = wkDiff.diff[it.key] || { delta: 0 };
      const delta = Number(d.delta) || 0;
      const sign = delta > 0
        ? statsT(game, 'weeklyDeltaPositive', { value: formatNumber(delta) })
        : delta < 0
          ? statsT(game, 'weeklyDeltaNegative', { value: formatNumber(delta) })
          : statsT(game, 'weeklyDeltaZero');
      const color = delta > 0 ? '#34d399' : delta < 0 ? '#f87171' : '#94a3b8';
      weeklyMetrics.push({ label: it.label, value: sign, valueStyle: `color:${color}` });
    }
  }

  return {
    sessionBanner: sessionBannerRow(game, 'growth'),
    progressionMetrics: [
      {
        label: statsT(game, 'playTime'),
        value: `${hours}h ${minutes}m ${seconds}s`,
        highlight: true,
        wide: true,
      },
      { label: statsT(game, 'currentZone'), value: String(zoneId), extra: zoneName },
      { label: statsT(game, 'maxTeamLevel'), value: String(maxLevel) },
      {
        label: statsT(game, 'offlineTimeSimulated'),
        value: formatDurationMs(s.offlineTimeSimulatedMs || 0),
      },
      { label: statsT(game, 'expeditionsLaunched'), value: formatNumber(s.expeditionLaunched || 0) },
    ],
    weeklyMetrics,
  };
}
