/**
 * @file src/stores/resourcesSnapshotGetter.ts
 * Optional bridge so publishHooks can read the live resources store without importing gameFacade.
 */

import type { ResourceSnapshot } from '../bus/snapshots.js';

let _getter: (() => ResourceSnapshot) | null = null;

export function registerResourcesSnapshotGetter(fn: () => ResourceSnapshot): void {
  _getter = fn;
}

export function getRegisteredResourcesSnapshot(): ResourceSnapshot | null {
  return _getter ? _getter() : null;
}
